export const bankWaiverDefinitions={
  bankWaiver:{title:'Compare a full-year fee waiver with the extra cash it requires',fields:[
    ['minimumBalance','Hypothetical minimum closing balance required for the waiver (CAD)',4000,500,10000,100],
    ['workingFloor','Minimum working cash already planned to stay in chequing (CAD)',1500,0,10000,100],
    ['monthlyFee','Monthly fee if the balance condition is not met (CAD)',15,0,40,1],
    ['alternativeRate','Assumed effective annual cash return after its tax and costs (%)',3,0,10,.5]
  ]}
};
export function bankWaiverPlan(input){
  const extra=Math.max(0,input.minimumBalance-input.workingFloor),annualBudget=input.monthlyFee*12;
  // Both choices qualify without extra cash when the existing floor is sufficient.
  const feesWithoutExtra=extra>0?annualBudget:0,interest=extra*input.alternativeRate/100;
  const withExtra=extra+annualBudget,withoutExtra=extra+interest+annualBudget-feesWithoutExtra;
  return {extra,annualBudget,feesWithoutExtra,interest,withExtra,withoutExtra,advantage:feesWithoutExtra-interest};
}
export function bankWaiverResult(kind,input){
  if(kind!=='bankWaiver')throw Error('Unknown bank-waiver topic.');
  const p=bankWaiverPlan(input);
  return {metrics:[['Annual fees avoided specifically by holding extra cash',p.feesWithoutExtra,'money'],['Assumed annual interest forgone on that extra cash',p.interest,'money'],['One-year resource difference: hold extra cash less do not add it',p.advantage,'money']],note:'Original hypothetical twelve-month comparison for the same account and included services. The entered working floor is the lowest closing balance already planned after ordinary transactions, not the average balance or the full emergency fund. Extra cash is the positive difference between the waiver threshold and that floor. Sufficient additional cash is assumed available at the start. Holding it keeps all waiver conditions satisfied for all twelve months and earns no interest in chequing. Without that extra cash, the fee is charged every month unless the existing floor already qualifies. Both choices start with the same extra cash and receive the same monthly household budget equal to the fee. Unspent monthly budget is retained separately at zero return. In the no-addition choice, the starting extra cash earns the selected effective annual return after its own tax and costs and is not used to pay fees. The normal working cash and other household resources are common and excluded. No actual account quote, daily transaction path, missed waiver, transfer delay, overdraft, product rebate, inflation or personal tax calculation is modeled.',charts:[
    {id:'bank-waiver-resources',type:'stackbar',title:'Match the starting cash and monthly household budget',unit:'money',unitLabel:'One-year nominal CAD resources shown in this matched comparison',seriesNames:['Starting extra cash retained','Unspent monthly fee budget retained','Interest on the alternative cash'],rows:[{label:'Hold the extra cash',values:[p.extra,p.annualBudget,0]},{label:'Do not add extra cash',values:[p.extra,p.annualBudget-p.feesWithoutExtra,p.interest]}],note:'The first choice keeps the extra principal in chequing and retains each avoided fee separately at zero return. The second keeps that same principal in the alternative cash account; fees come from the identical monthly household budget. The principal remains an asset in both choices. When the working floor already meets the threshold, both qualify and retain the same monthly budget without needing extra cash.'},
    {id:'bank-waiver-net-value',type:'waterfall',title:'Subtract the extra cash’s opportunity cost from the avoided fees',unit:'money',rows:[{label:'Fees avoided by the extra balance',value:p.feesWithoutExtra},{label:'Less interest forgone elsewhere',value:-p.interest}],totalLabel:'One-year resource advantage',note:'A positive result favours holding the extra balance under these assumptions; a negative result favours leaving it in the alternative cash account and paying the fee. This is a comparison of resources after one year, not interest paid by the chequing account or an investment return quoted by a bank.'},
    {id:'bank-waiver-return-hurdle',type:'line',title:'Find the alternative cash return that changes the comparison',unit:'money',xLabel:'Alternative annual return (%)',series:[{name:'Extra-balance choice less no-addition choice',rows:Array.from({length:21},(_,i)=>({x:i/2,value:bankWaiverPlan({...input,alternativeRate:i/2}).advantage}))},{name:'Equal resources after one year',rows:[{x:0,value:0},{x:10,value:0}],dash:true}],note:'The horizontal axis varies only the effective annual return after the alternative cash account’s tax and costs. Other inputs stay entered. With a positive extra balance, the break-even rate is annual fees avoided divided by extra cash. A crossing outside the displayed 0%–10% range is not shown. When no extra cash is needed, both choices already qualify and the difference is zero at every rate.'},
    {id:'bank-waiver-balance-grid',type:'heatmap',title:'The monthly fee and additional cash requirement work together',unit:'money',signed:true,columns:['CAD 1k','CAD 2.5k','CAD 4k','CAD 6k'],rows:[10,15,20,30].map(fee=>({label:fee+'/month',values:[1000,2500,4000,6000].map(extra=>12*fee-extra*input.alternativeRate/100)})),unitLabel:'One-year advantage of holding the positive extra balance (CAD)',note:'Rows replace the monthly fee; columns replace the extra cash needed above the normal working floor, not the total minimum balance. These positive-extra scenarios assume all twelve fees are avoided and retain the entered alternative return. The two balance inputs are replaced by each column’s extra requirement. Gold cells are negative and teal cells are positive. These are scenarios, not account offers or probabilities.'}
  ]};
}
